node - <<'NODE'
const { chromium } = require('playwright');
(async()=>{
  const browser = await chromium.launch({headless:true});
  const page = await browser.newPage();
  await page.goto('file:///app/output/final_poster.png');
  const dims = await page.evaluate(() => ({w: document.querySelector('img').naturalWidth, h: document.querySelector('img').naturalHeight}));
  console.log(dims);
  await browser.close();
})();
